import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DhRvvru9.js";const u=JSON.parse('{"title":"Building & packaging","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build.md","filePath":"guide/build.md"}'),o={name:"guide/build.md"};function n(d,e,l,r,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="building-packaging" tabindex="-1">Building &amp; packaging <a class="header-anchor" href="#building-packaging" aria-label="Permalink to &quot;Building &amp; packaging&quot;">​</a></h1><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Runs the Vite dev server and the Java app together, restarting the Java side automatically when a <code>.java</code> file under <code>lib/src</code> changes (the frontend gets Vite&#39;s own HMR). Auto-detects the right Gradle task and root by walking up from the current directory to the nearest <code>settings.gradle.kts</code></p><ul><li>pass <code>--task</code>/<code>--gradle-dir</code> explicitly if it guesses wrong (e.g. a non-standard <code>frontend/</code>+<code>lib/</code> layout).</li></ul><p>See <a href="/sugr/guide/debug">Debugging</a> for <code>sugr debug</code> - attaching a real IDE debugger to the backend and/or frontend.</p><p><code>sugr dev</code> defaults to the <code>dev</code> environment; pass <code>--env staging</code>/<code>--env prod</code> to run against a different one instead (also accepted by <code>sugr build</code> and <code>sugr debug</code>) - see <a href="/sugr/guide/environments">Environments</a>.</p><h2 id="sugr-build-vs-sugr-package-which-one-do-i-need" tabindex="-1"><code>sugr build</code> vs. <code>sugr package</code>: which one do I need? <a class="header-anchor" href="#sugr-build-vs-sugr-package-which-one-do-i-need" aria-label="Permalink to &quot;\`sugr build\` vs. \`sugr package\`: which one do I need?&quot;">​</a></h2><ul><li><strong><code>sugr build</code></strong> → a runnable <strong>JAR</strong>. Fast (no native-image compile), works the same on every OS, but the machine running it needs a JVM installed. Good for a quick &quot;does the production-embedded frontend actually work&quot; check, or for environments where requiring a JVM is fine (internal tools, servers).</li><li><strong><code>sugr package</code></strong> → a standalone <strong>native binary + OS installer</strong>, no JVM needed on the target machine. This is what you ship to end users - but it costs more to build (native-image&#39;s whole-program compile is slow) and needs extra local setup (see below).</li></ul><div class="warning custom-block"><p class="custom-block-title"><code>sugr package</code> doesn&#39;t re-embed the frontend itself</p><p><code>sugr package</code> only runs <code>nativeCompile</code> - it does <em>not</em> run <code>pnpm build</code> or copy <code>frontend/dist/</code> into <code>lib/src/main/resources/frontend</code> the way <code>sugr build</code> does. It packages whatever is already sitting in that resources folder, so if you&#39;ve changed the frontend since your last <code>sugr build</code>, run <code>sugr build</code> (or at least its frontend-embed step) again first - otherwise <code>sugr package</code> ships a stale (or, on a fresh checkout, missing) frontend.</p></div><h2 id="production-build-jar" tabindex="-1">Production build (JAR) <a class="header-anchor" href="#production-build-jar" aria-label="Permalink to &quot;Production build (JAR)&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><ol><li><code>pnpm build</code> in <code>frontend/</code> (passing <code>--mode &lt;env&gt;</code>, defaulting to <code>prod</code>)</li><li>Copies <code>frontend/dist/</code> into <code>lib/src/main/resources/frontend</code></li><li>Runs the Gradle build</li></ol><p>The result is a runnable JAR (via <code>gradle run</code>, or the <code>application</code> plugin&#39;s distribution) that serves the embedded frontend - still needs a JVM installed on the machine that runs it.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span></span></code></pre></div><p>See <a href="/sugr/guide/environments">Environments</a> for how <code>--env</code> selects <code>.env.&lt;env&gt;</code> on the frontend and <code>application-&lt;env&gt;.properties</code> on the backend.</p><h2 id="native-binary-installer" tabindex="-1">Native binary + installer <a class="header-anchor" href="#native-binary-installer" aria-label="Permalink to &quot;Native binary + installer&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>Builds a native-image binary (via Gradle&#39;s <code>nativeCompile</code> task - every app generated from the <code>react-ts</code> template has the <a href="https://graalvm.github.io/native-build-tools/latest/gradle-plugin.html" target="_blank" rel="noreferrer">GraalVM native-image Gradle plugin</a> wired up already) and wraps it directly into an OS installer - no JVM involved at all in the final artifact. On Windows this is genuinely one command with nothing to set up first: <code>sugr package</code> locates your Visual Studio install and sources its <code>vcvars64.bat</code> itself (native-image&#39;s C compiler step needs <code>cl.exe</code>/<code>link.exe</code> on PATH, which a plain terminal doesn&#39;t have - this used to mean manually opening a &quot;Developer Command Prompt for VS&quot; before building), then wraps the resulting <code>.exe</code> with <a href="https://nsis.sourceforge.io/" target="_blank" rel="noreferrer">NSIS</a> into a proper installer (Start Menu + desktop shortcuts, uninstaller, and a check that silently installs the WebView2 Runtime if the target machine doesn&#39;t have it yet). macOS (<code>.dmg</code> via <code>hdiutil</code>) and Linux (<code>.deb</code> via <code>dpkg-deb</code>) follow the same shape in the code but haven&#39;t been exercised on those OSes yet.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sugr package [--name &lt;name&gt;] [--app-version &lt;version&gt;] [--icon &lt;path&gt;]</span></span>
<span class="line"><span>             [--lib-dir lib] [--dest dist]</span></span></code></pre></div><p><code>--name</code>/<code>--app-version</code>/<code>--icon</code> default to a <code>sugr.config.json</code> in your app&#39;s root directory (alongside <code>frontend/</code> and <code>lib/</code>), if present:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;appVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;icon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assets/icon.ico&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>CLI flags always override the file; both are optional (falls back to <code>sugr-app</code>/<code>0.1.0</code>/no icon). The <code>react-ts</code> template ships one with <code>&quot;name&quot;</code> pre-filled from <code>sugr init</code>&#39;s app name.</p><p>If your app calls into a native library of its own beyond <code>core</code>&#39;s webview binding (like <code>examples/sql-client</code> does with <code>libsqlite3</code>), you&#39;ll need to (re-)generate FFM reachability metadata once: run the app on a plain JVM with <code>-agentlib:native-image-agent=config-output-dir=...</code> attached, exercise every code path that makes a native call, close the app normally (not force-killed</p><ul><li>the agent only writes its config on a graceful JVM shutdown), then copy the resulting <code>reachability-metadata.json</code> into your module&#39;s <code>src/main/resources/META-INF/native-image/&lt;any&gt;/&lt;any&gt;/</code>. The <code>react-ts</code> template already ships the metadata for <code>core</code>&#39;s own webview bindings, so a fresh <code>sugr init</code> app can run <code>sugr package</code> immediately - this step is only needed once you add your own native library.</li></ul><h2 id="what-s-not-automated-yet" tabindex="-1">What&#39;s not automated yet <a class="header-anchor" href="#what-s-not-automated-yet" aria-label="Permalink to &quot;What&#39;s not automated yet&quot;">​</a></h2><ul><li>Publishing <code>core</code>/<code>bridge</code>/<code>processor</code> to Maven Central or <code>@sugr/runtime</code> to npm</li></ul>`,27)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
